/**
 * Token Generator — SRKR Cafeteria
 * 
 * Generates readable, collision-resistant tokens for demo use.
 * Format: SRK-001, SRK-002, etc.
 * 
 * ⚠ DEMO-ONLY: This frontend token generator uses a localStorage counter.
 * It CANNOT guarantee globally unique tokens across multiple devices or
 * concurrent users. In production, tokens must be generated by the backend.
 * 
 * This utility is isolated so it can be replaced by a backend API call
 * without modifying any UI components.
 */

const TOKEN_COUNTER_KEY = 'srkr_token_counter';

/**
 * Get the current counter value from localStorage.
 * @returns {number}
 */
function getCounter() {
  try {
    const val = localStorage.getItem(TOKEN_COUNTER_KEY);
    const num = parseInt(val, 10);
    return isNaN(num) ? 0 : num;
  } catch {
    return 0;
  }
}

/**
 * Save the counter value to localStorage.
 * @param {number} value
 */
function setCounter(value) {
  try {
    localStorage.setItem(TOKEN_COUNTER_KEY, String(value));
  } catch {
    // Storage unavailable — silent fail in demo
  }
}

/**
 * Generate a new unique token string.
 * Each call increments the counter and returns a formatted token.
 * 
 * @returns {string} Token like "SRK-001"
 */
export function generateToken() {
  const current = getCounter() + 1;
  setCounter(current);
  const padded = String(current).padStart(3, '0');
  return `SRK-${padded}`;
}

/**
 * Generate a unique order ID.
 * Combines timestamp with a random segment for collision resistance.
 * 
 * @returns {string} Order ID like "ORD-1698234567890-a3f2"
 */
export function generateOrderId() {
  const timestamp = Date.now();
  const random = Math.random().toString(36).substring(2, 6);
  return `ORD-${timestamp}-${random}`;
}

/**
 * Reset the token counter (for demo/testing purposes only).
 */
export function resetTokenCounter() {
  setCounter(0);
}
